declare(strict_types=1); define('SAAS_NO_GLOBAL_NAV',true); require_once __DIR__.'/finance.php'; require_finance_admin(); $pdo=db();$month=date('Y-m');$from=$month.'-01';$to=date('Y-m-d',strtotime($from.' +1 month'));
$activeClients=(int)$pdo->query("SELECT COUNT(*) FROM clients WHERE active=1")->fetchColumn();$activeEmployees=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='employee' AND active=1")->fetchColumn();$q=$pdo->prepare('SELECT COALESCE(SUM(amount_received),0) FROM client_payments WHERE invoice_date>=? AND invoice_date<?');$q->execute([$from,$to]);$income=(float)$q->fetchColumn();$q=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM office_expenses WHERE date>=? AND date<?');$q->execute([$from,$to]);$expenses=(float)$q->fetchColumn();$pendingApprovals=(int)$pdo->query("SELECT COUNT(*) FROM content WHERE status='pending'")->fetchColumn();$pendingLeaves=(int)$pdo->query("SELECT COUNT(*) FROM leave_requests WHERE status='pending'")->fetchColumn();$overdue=(int)$pdo->query("SELECT COUNT(*) FROM client_payments WHERE pending_amount>0 AND due_date<CURDATE()")->fetchColumn();$recent=$pdo->query('SELECT c.id,c.title,c.status,c.updated_at,cl.name client_name FROM content c JOIN clients cl ON cl.id=c.client_id ORDER BY c.updated_at DESC LIMIT 10')->fetchAll();function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
